def choose_move(observation):
    # Defensive defaults
    grid_h = observation.get("grid_height", 0)
    grid_w = observation.get("grid_width", 0)
    pos = observation.get("agent_position", observation.get("position", [0, 0]))
    x, y = pos[0], pos[1]

    # Initialize movement to stay in place
    dx, dy = 0, 0

    # Helpers to safely read resources, enemies, allies, territories
    def has_resource_at(nx, ny):
        resources = observation.get("resources", [])
        for r in resources:
            if (r.get("x") == nx and r.get("y") == ny):
                return True
        return False

    def is_agent_at(nx, ny):
        others = observation.get("agents", [])
        for a in others:
            if a.get("x") == nx and a.get("y") == ny:
                return True
        return False

    # Attempt simple robust policy:
    # 1) If there is a resource at current or adjacent cell, move towards it.
    # 2) If under pursuit_evasion setting: try to move away from nearest threat.
    # 3) Otherwise, patrol towards center or a safe default.

    # Gather nearby cells in order of preference: up, down, left, right, stay
    candidates = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    # Check for resource in adjacent cells or current
    best = None
    for dxi, dyi in [(0,0)] + candidates:
        nx, ny = x + dxi, y + dyi
        if 0 <= nx < grid_w and 0 <= ny < grid_h:
            if dxi == 0 and dyi == 0:
                # stay as a fallback
                if best is None:
                    best = (0, 0)
                continue
            if has_resource_at(nx, ny):
                best = (dxi, dyi)
                break

    if best is None:
        # Try to move away from nearest threat if present
        threats = observation.get("threats", [])
        if threats:
            # compute a simple vector away from closest threat
            min_dist = None
            away = None
            for t in threats:
                tx, ty = t.get("x"), t.get("y")
                if tx is None or ty is None:
                    continue
                dist = abs(x - tx) + abs(y - ty)
                if min_dist is None or dist < min_dist:
                    min_dist = dist
                    # prefer opposite direction
                    ax = x - tx
                    ay = y - ty
                    away = (0 if ax == 0 else (1 if ax > 0 else -1),
                            0 if ay == 0 else (1 if ay > 0 else -1))
            if away is not None and away != (0,0):
                best = away

    if best is None:
        # Patrol towards center if grid known
        if grid_w > 0 and grid_h > 0:
            cx = (grid_w - 1) // 2
            cy = (grid_h - 1) // 2
            dx_step = 0 if x == cx else (1 if cx > x else -1)
            dy_step = 0 if y == cy else (1 if cy > y else -1)
            # Prefer horizontal move first to reduce oscillation
            if dx_step != 0:
                best = (dx_step, 0)
            elif dy_step != 0:
                best = (0, dy_step)

    if best is None:
        best = (0, 0)

    dx, dy = best
    # Bound within allowed set and return
    if dx not in (-1, 0, 1) or dy not in (-1, 0, 1):
        dx, dy = 0, 0
    return [dx, dy]

